const FUEL_PER_KM = 3;
const LONG_TRIP_KM = 1000;
const LONG_TRIP_EXTRA = 200;

function fuelNeeded(distanceKm) {
  const extra = distanceKm > LONG_TRIP_KM ? LONG_TRIP_EXTRA : 0;
  return distanceKm * FUEL_PER_KM + extra;
}

console.log(fuelNeeded(500));
console.log(fuelNeeded(2000));

check.js:
assert(FUEL_PER_KM === 3 && LONG_TRIP_KM === 1000 && LONG_TRIP_EXTRA === 200, "Üç sabit doğru değerlerle tanımlanmalı.");
assert(fuelNeeded(500) === 1500 && fuelNeeded(1000) === 3000 && fuelNeeded(2000) === 6200 && fuelNeeded(1001) === 3203, "fuelNeeded eski f ile aynı sonuçları vermeli.");
assert(!/\b(3|1000|200)\b/.test(fuelNeeded.toString()), "fuelNeeded içinde 3, 1000 ya da 200 yazma; sabitleri kullan.");
assert(_lines.join(",") === "1500,6200", "Çıktı 1500 ve 6200 olmalı.");

