tasks.solution:
const MIN_FUEL = 50;

function canLaunch(ship) {
  if (!ship) return "Gemi yok";
  const { fuel, crew } = ship;
  if (fuel < MIN_FUEL) return "Yakıt az";
  if (crew <= 0) return "Mürettebat yok";
  return "Kalkış!";
}

console.log(canLaunch({ fuel: 80, crew: 3 }));

check.js:
assert(MIN_FUEL === 50, "MIN_FUEL 50 olmalı.");
assert(canLaunch(null) === "Gemi yok" && canLaunch(undefined) === "Gemi yok", "Gemi yoksa 'Gemi yok' döndürmeli.");
assert(canLaunch({ fuel: 10, crew: 3 }) === "Yakıt az" && canLaunch({ fuel: 49, crew: 0 }) === "Yakıt az", "Yakıt 50'den azsa 'Yakıt az' döndürmeli.");
assert(canLaunch({ fuel: 80, crew: 0 }) === "Mürettebat yok", "Mürettebat yoksa 'Mürettebat yok' döndürmeli.");
assert(canLaunch({ fuel: 50, crew: 2 }) === "Kalkış!", "Her şey tamamsa 'Kalkış!' döndürmeli.");
const src = canLaunch.toString();
assert(!/\belse\b/.test(src), "canLaunch içinde else kalmamalı; erken dönüş kullan.");
assert(/\{\s*[\w\s,]+\}\s*=/.test(src), "fuel ve crew'u parçalama ile al: const { fuel, crew } = ship;");
assert(!/\b50\b/.test(src), "canLaunch içinde 50 yazma; MIN_FUEL kullan.");

