const STAR_POINTS = 10;
const BONUS_EVERY = 50;
const START_LIVES = 3;

function collectStar(game) {
  game.score += STAR_POINTS;
  // her BONUS_EVERY puanda bir ödül canı
  if (game.score % BONUS_EVERY === 0) game.lives += 1;
}

function hitEnemy(game) {
  game.lives = Math.max(0, game.lives - 1);
}

function isGameOver(game) {
  return game.lives === 0;
}

const game = { score: 0, lives: START_LIVES };
collectStar(game);
hitEnemy(game);
console.log(`Skor: ${game.score} | Can: ${game.lives}`);

check.js:
assert(STAR_POINTS === 10 && BONUS_EVERY === 50 && START_LIVES === 3, "Üç sabit doğru değerlerle tanımlanmalı.");
const g = { score: 40, lives: 1 };
collectStar(g);
assert(g.score === 50 && g.lives === 2, "40 puandan yıldız toplayınca skor 50 olmalı ve bir can kazanılmalı.");
collectStar(g);
assert(g.score === 60 && g.lives === 2, "60 puanda can kazanılmamalı.");
const h = { score: 0, lives: 1 };
hitEnemy(h);
assert(h.lives === 0, "hitEnemy bir can azaltmalı.");
hitEnemy(h);
assert(h.lives === 0, "Can 0'ın altına inmemeli.");
assert(isGameOver(h) === true && isGameOver({ score: 0, lives: 2 }) === false, "isGameOver can 0 ise true, değilse false döndürmeli.");
assert(!/\b(10|50)\b/.test(collectStar.toString()), "collectStar içinde 10 ya da 50 yazma; sabitleri kullan.");
assert(game.score === 10 && game.lives === 2 && _lines.includes("Skor: 10 | Can: 2"), "Sonunda 'Skor: 10 | Can: 2' yazdırmalısın.");

