const MENU_LINKS = [
  { text: "Ana sayfa", href: "#home" },
  { text: "Blog", href: "#blog" },
  { text: "Projeler", href: "#projects" },
];

function createLink({ text, href }) {
  const link = document.createElement("a");
  link.textContent = text;
  link.href = href;
  link.className = "link";
  return link;
}

function renderMenu(links) {
  const menu = document.querySelector("#menu");
  menu.innerHTML = "";
  links.forEach((link) => menu.append(createLink(link)));
}

renderMenu(MENU_LINKS);

check.js:
const texts = () => $$("#menu a.link").map((a) => a.textContent.trim()).join(",");
assert(texts() === "Ana sayfa,Blog,Projeler", "#menu içinde Ana sayfa, Blog, Projeler bağlantıları (link sınıfıyla) olmalı.");
assert(Array.isArray(MENU_LINKS) && MENU_LINKS.length === 3, "MENU_LINKS 3 bağlantılı bir dizi olmalı.");
const a = createLink({ text: "X", href: "#x" });
assert(a && a.tagName === "A" && a.textContent === "X" && a.getAttribute("href") === "#x" && a.classList.contains("link"), "createLink bir <a> döndürmeli (metin, href ve link sınıfıyla).");
renderMenu([{ text: "İletişim", href: "#contact" }]);
