project_task.solution:
function countDone(tasks) {
  return tasks.filter((task) => task.done).length;
}

function percentDone(tasks) {
  if (tasks.length === 0) return 0;
  return Math.round((countDone(tasks) / tasks.length) * 100);
}

function statsText(tasks) {
  return `Tamamlanan: ${countDone(tasks)}/${tasks.length} (%${percentDone(tasks)})`;
}

const list = [{ title: "Matematik", done: true }, { title: "Fizik", done: false }];
console.log(statsText(list));

check.js:
const three = [{ title: "A", done: true }, { title: "B", done: false }, { title: "C", done: false }];
assert(countDone(three) === 1 && countDone([]) === 0, "countDone bitmiş görevleri saymalı.");
assert(percentDone(three) === 33, "3 görevden 1'i bitince percentDone 33 olmalı.");
assert(percentDone([]) === 0, "Boş listede percentDone 0 döndürmeli.");
assert(statsText(three) === "Tamamlanan: 1/3 (%33)", "statsText 'Tamamlanan: 1/3 (%33)' döndürmeli.");
assert(statsText([]) === "Tamamlanan: 0/0 (%0)", "Boş listede statsText 'Tamamlanan: 0/0 (%0)' döndürmeli.");
