project_task.solution:
const GREAT_PERCENT = 90;
const PASS_PERCENT = 60;

function percent(correct, total) {
  if (total === 0) return 0;
  return Math.round((correct / total) * 100);
}

function resultMessage({ correct, total }) {
  const p = percent(correct, total);
  if (p >= GREAT_PERCENT) return `Harika! (%${p})`;
  if (p >= PASS_PERCENT) return `Geçtin (%${p})`;
  return `Tekrar dene (%${p})`;
}

console.log(resultMessage({ correct: 4, total: 5 }));

check.js:
assert(GREAT_PERCENT === 90 && PASS_PERCENT === 60, "GREAT_PERCENT 90, PASS_PERCENT 60 olmalı.");
assert(percent(3, 5) === 60 && percent(1, 3) === 33 && percent(0, 0) === 0, "percent yuvarlanmış yüzdeyi vermeli; total 0 ise 0.");
assert(resultMessage({ correct: 5, total: 5 }) === "Harika! (%100)", "5/5 için 'Harika! (%100)' olmalı.");
assert(resultMessage({ correct: 9, total: 10 }) === "Harika! (%90)", "9/10 için 'Harika! (%90)' olmalı.");
assert(resultMessage({ correct: 3, total: 5 }) === "Geçtin (%60)", "3/5 için 'Geçtin (%60)' olmalı.");
assert(resultMessage({ correct: 1, total: 4 }) === "Tekrar dene (%25)", "1/4 için 'Tekrar dene (%25)' olmalı.");
assert(resultMessage({ correct: 0, total: 0 }) === "Tekrar dene (%0)", "Soru yoksa 'Tekrar dene (%0)' olmalı.");
assert(!/\belse\b/.test(resultMessage.toString()), "resultMessage içinde else olmamalı; erken dönüş kullan.");
assert(_lines.includes("Geçtin (%80)"), "Çıktıda 'Geçtin (%80)' görünmeli.");
